  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  assert.equal(totals.subtotal, 98700);
  assert.equal(totals.vat, 20283); // 19950 + 333
  assert.equal(totals.total, 118983); // 98700 + 20283
});

test('invoiceTotals with discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
