  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  // Line total: 95000, discount: 9500, amount after discount: 85500
  // VAT at 21%: 17955
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455); // 95000 - 9500 + 17955
});

test('invoiceTotals with multiple VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 }, // 9% VAT
