test('invoiceTotals with created invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }, // explicit 0% to bypass tier discount
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
    ],
