});

test('removeLine does not mutate the input invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(r1.ok, true);
  const originalLines = JSON.parse(JSON.stringify(r1.value.lines));

  removeLine(r1.value, 'DEV-HOUR');

  assert.deepEqual(r1.value.lines, originalLines);
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

