  assert.equal(r2.value.lines[1].discountPercent, 5); // gold tier discount
});

test('addLine respects explicit discountPercent over tier discount', () => {
  const r1 = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

