test('lineDiscount calculates discount correctly', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500, discountPercent: 10 }), 9500); // 950 * 0.1 = 95 euros = 9500 cents
  assert.equal(lineDiscount({ qty: 1, unitPrice: 120000, discountPercent: 10 }), 12000); // 1200 * 0.1 = 120 euros = 12000 cents
});

test('lineDiscount defaults to 0% if discountPercent not provided', () => {
