  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 10);
});

test('createInvoice explicit 0% discount overrides tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 0);
});

test('createInvoice with multiple lines applies tier discount to all', () => {
  const r = createInvoice({
    customerId: 'C-003', // silver tier (2.5%)
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 2.5);
  assert.equal(r.value.lines[1].discountPercent, 2.5);
});

test('createInvoice allows mixed explicit and tier discounts', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 }, // uses tier discount 5%
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 }, // explicit 15%
    ],
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].discountPercent, 5);
  assert.equal(r.value.lines[1].discountPercent, 15);
});

test('addLine applies tier discount when no discountPercent provided', () => {
  const r1 = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
  });

  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1 });

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 5); // gold tier discount
});

test('addLine respects explicit discountPercent over tier discount', () => {
  const r1 = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(r1.ok, true);
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 });

  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 20);
});

test('lineVAT calculates VAT on line amount after discount', () => {
  // DEV-HOUR: unitPrice 9500, qty 10, no discount
  // Line total: 95000, VAT at 21%: 19950
  const line1 = { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 };
  assert.equal(lineVAT(line1), 19950);

  // With 10% discount: line total 85500, VAT at 21%: 17955
  const line2 = { qty: 10, unitPrice: 9500, discountPercent: 10, vatRate: 21 };
  assert.equal(lineVAT(line2), 17955);
});

test('lineVAT with 0% VAT rate returns 0', () => {
  const line = { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 0 };
  assert.equal(lineVAT(line), 0);
});

test('lineVAT with 9% VAT rate', () => {
  // PRINT-A4: unitPrice 37, qty 100 (line total 3700)
  // VAT at 9%: 333
  const line = { qty: 100, unitPrice: 37, discountPercent: 0, vatRate: 9 };
  assert.equal(lineVAT(line), 333);
});

test('lineVAT is clamped to 0', () => {
  const line = { qty: 0, unitPrice: 9500, discountPercent: 0, vatRate: 21 };
  assert.equal(lineVAT(line), 0);
});

test('invoiceTotals includes VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  // Line total: 95000, no discount, VAT at 21%: 19950
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 19950);
  assert.equal(totals.total, 114950); // 95000 + 19950
});

test('invoiceTotals VAT is computed per line and rounded', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }, // 95000, VAT 19950
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 }, // 3700, VAT 333
    ],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  assert.equal(totals.subtotal, 98700);
  assert.equal(totals.vat, 20283); // 19950 + 333
  assert.equal(totals.total, 118983); // 98700 + 20283
});

test('invoiceTotals with discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  // Line total: 95000, discount: 9500, amount after discount: 85500
  // VAT at 21%: 17955
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455); // 95000 - 9500 + 17955
});

test('invoiceTotals with multiple VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }, // 21% VAT
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 }, // 9% VAT
      { sku: 'WORKSHOP-DAY', qty: 1, discountPercent: 0 }, // 0% VAT
    ],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  // DEV-HOUR: subtotal 95000, VAT 19950
  // PRINT-A4: subtotal 3700, VAT 333
  // WORKSHOP-DAY: subtotal 60000, VAT 0
  assert.equal(totals.subtotal, 158700);
  assert.equal(totals.vat, 20283); // 19950 + 333 + 0
  assert.equal(totals.total, 178983);
});

